    private final class GearButton extends View {
        private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);
        GearButton(Context context){super(context);setClickable(true);setFocusable(true);}
        @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);float cx=getWidth()/2f,cy=getHeight()/2f;float scale=dp(24)/24f;paint.setColor(color("#345C56"));paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(1.8f*scale);paint.setStrokeCap(Paint.Cap.ROUND);canvas.drawCircle(cx,cy,5.5f*scale,paint);canvas.drawCircle(cx,cy,1.6f*scale,paint);for(int i=0;i<8;i++){double a=Math.PI*i/4;float x=(float)Math.cos(a),y=(float)Math.sin(a);canvas.drawLine(cx+6.5f*scale*x,cy+6.5f*scale*y,cx+8.5f*scale*x,cy+8.5f*scale*y,paint);}}
    }
