    private String endpoint(){return getPreferences(0).getString("endpoint",BASE);}
    private String validateEndpoint(String value)throws Exception{URI u=new URI(value.trim());if(!"https".equalsIgnoreCase(u.getScheme())||u.getHost()==null||u.getRawUserInfo()!=null||u.getRawQuery()!=null||u.getRawFragment()!=null)throw new IOException("请输入完整 HTTPS 地址，不要包含用户名、密码、参数或片段。");return u.normalize().toASCIIString();}
    private GradientDrawable outlined(){GradientDrawable d=bg("#EEF3F0",4);d.setStroke(dp(1),color("#79747E"));return d;}
