        LinearLayout header=new LinearLayout(this);header.setGravity(Gravity.CENTER_VERTICAL);page.addView(header,new LinearLayout.LayoutParams(-1,dp(48)));TextView back=label("‹",30,"#345C56",false);back.setGravity(Gravity.CENTER_VERTICAL);back.setContentDescription("返回");header.addView(back,new LinearLayout.LayoutParams(dp(40),-1));back.setOnClickListener(v->closeSettings());header.addView(label("设置",23,"#1B2226",true));
        gap(page,26);page.addView(label("模型服务",18,"#202826",true));gap(page,9);page.addView(label("连接你自己的 DashScope 账号",13,"#69757A",false));gap(page,28);
        LinearLayout card=column();card.setPadding(dp(20),dp(20),dp(20),dp(20));card.setBackground(bg("#EEF3F0",24));page.addView(card,new LinearLayout.LayoutParams(-1,-2));card.addView(label("服务连接",16,"#294A43",true));gap(card,9);card.addView(label("密钥仅加密保存在这台设备",13,"#697F76",false));gap(card,20);
        EditText url=settingsField(card,"请求地址","完整 HTTPS 请求地址",android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI,endpoint());gap(card,12);EditText input=settingsField(card,"API Key","留空保留已保存的密钥",129,null);gap(card,40);
        LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER_VERTICAL);card.addView(actions,new LinearLayout.LayoutParams(-1,dp(48)));TextView remove=label("删除已保存的密钥",13,"#835350",true);remove.setGravity(Gravity.CENTER_VERTICAL);remove.setContentDescription("删除已保存的密钥");actions.addView(remove,new LinearLayout.LayoutParams(0,-1,1));remove.setOnClickListener(v->{getPreferences(0).edit().remove("key").remove("iv").apply();input.setText("");toast("已删除密钥");});Button save=new Button(this);save.setText("保存密钥");save.setTextSize(14);save.setAllCaps(false);save.setTextColor(-1);save.setPadding(dp(16),0,dp(16),0);save.setBackground(bg("#6750A4",24));actions.addView(save,new LinearLayout.LayoutParams(-2,dp(44)));
        save.setOnClickListener(v->{try{String address=validateEndpoint(url.getText().toString());String value=input.getText().toString().trim();if(!value.isEmpty())saveKey(value);String previous=endpoint();getPreferences(0).edit().putString("endpoint",address).apply();if(!previous.equals(address)){resultTitle.setText("从一句话开始");resultSubtitle.setText("输入场景、物品或记忆中的细节");showEmpty();toast("地址已保存，请为当前服务建立索引。");}else toast("设置已保存");closeSettings();}catch(Exception e){url.setError(e instanceof IOException?e.getMessage():"保存失败，请检查请求地址。");}});
        gap(page,40);page.addView(label("关于连接",16,"#202826",true));gap(page,14);page.addView(label("图片与搜索文字会发送至所配置的服务。",13,"#69757A",false));gap(page,14);page.addView(label("模型：qwen3-vl-embedding",13,"#69757A",false));gap(page,9);page.addView(label("默认：中国北京 DashScope",13,"#69757A",false));
